from pathlib import Path
import base64

PATH = Path("components/portal/mobile-portal-navigation.tsx")

if not PATH.exists():
    raise SystemExit(
        "Missing components/portal/mobile-portal-navigation.tsx. "
        "Run the earlier mobile shell patch first."
    )

current = PATH.read_text(encoding="utf-8")

if "export function MobilePortalNavigation" not in current:
    raise SystemExit(
        "Unexpected mobile navigation file. "
        "No changes made."
    )

replacement = base64.b64decode("").decode("utf-8")
PATH.write_text(replacement, encoding="utf-8")

print("✓ Mobile policy rules preserved")
print("✓ Existing desktop modal event reused")
print("✓ People and Messages bottom buttons open modals")
print("✓ Lore / Market / Crafting / Missions / Forum / legal modal items open modals")
print("✓ Direct-only items remain direct")
print("✓ Existing bottom-bar PNG icons preserved")
print("")
print("Run: npm run build")
